insert into challenges (id, category, title, teaser, description, steps, tips, difficulty, minutes, equipment, gear, icon, easier, harder, safety, caption, result_type, result_unit) values
('d01-bieg-otwarcia', 'RUNNING', 'BIEG OTWARCIA', '40 minut w strefie 2 i cztery przebieżki. Grudzień oficjalnie otwarty.', 'Spokojny start kalendarza: 40 minut biegu w tempie konwersacyjnym, a na koniec cztery krótkie przebieżki, żeby nogi przypomniały sobie, że umieją też szybciej. Zero ścigania, czysta baza.', '["Rozgrzej się 5 minut marszem lub bardzo wolnym truchtem.","Biegnij 40 minut w strefie 2: tak, żeby swobodnie mówić pełnymi zdaniami.","Na koniec 4 × 20 s przebieżki (szybko, luźno, na palcach), między nimi 60 s marszu.","Zrób zrzut ekranu z zegarka lub Stravy i zapisz dystans."]'::jsonb, 'Jeśli nie mierzysz tętna, oddychaj nosem. Gdy przestaje wystarczać, zwolnij.', 'EASY', 50, '[]'::jsonb, 'NONE', 'footprints', '30 minut biegu z marszem (np. 4 min biegu / 1 min marszu) i 2 przebieżki.', '60 minut w Z2 i 6 przebieżek.', '', 'Dzień 1. Spokojnie, bo to dopiero początek. Grudzień: otwarty.', 'DISTANCE', 'km'),
('d02-reset-bioder', 'MOBILITY', 'RESET BIODER', '20 minut dla bioder, które biegają, kręcą i siedzą przy biurku.', 'Biodra wytrzymałościowca mają ciężkie życie: setki tysięcy powtórzeń w jednej płaszczyźnie i osiem godzin siedzenia. Dziś dajesz im pełen zakres ruchu.', '["90/90 z przejściami: 2 × 8 przejść na stronę.","Couch stretch (rozciąganie zginaczy przy ścianie lub kanapie): 2 × 60 s na nogę.","Gołąb (pigeon pose): 2 × 60 s na stronę.","Most biodrowy na jednej nodze: 2 × 12 na stronę.","Głęboki przysiad z rotacjami tułowia: 2 minuty."]'::jsonb, 'Przy couch stretch ściśnij pośladek nogi z tyłu, wtedy rozciągasz biodro, a nie lędźwie.', 'EASY', 20, '["Mata lub koc"]'::jsonb, 'NONE', 'rotate', 'Tylko 90/90 i couch stretch, po jednej serii.', 'Dodaj Cossack squat 2 × 6 na stronę i zrób całość dwa razy.', '', 'Reset bioder zaliczony. Biodra przestały skrzypieć. Na razie.', 'NOTE', ''),
('d03-progresja', 'RUNNING', 'PROGRESJA 6 × 1 KM', 'Sześć kilometrów, każdy trochę szybszy od poprzedniego.', 'Bieg progresywny uczy kontroli tempa i kończenia mocno. Zaczynasz bardzo spokojnie, a każdy kolejny kilometr jest o kilka sekund szybszy. Ostatni ma być szybki, ale nie maksymalny.', '["Rozgrzewka: 10 minut spokojnego truchtu.","Km 1–2: tempo spokojne (Z2).","Km 3–4: tempo umiarkowane, oddech wyraźnie głębszy.","Km 5–6: tempo „comfortably hard”, czyli ok. tempa półmaratonu lub 10 km.","Schłodzenie: 5 minut truchtu. Zapisz czas ostatniego kilometra."]'::jsonb, 'Kluczem jest pierwszy kilometr. Jeśli zaczniesz za szybko, progresja zamieni się w regresję.', 'MEDIUM', 55, '[]'::jsonb, 'NONE', 'trending-up', '4 km progresji (2 spokojnie, 2 umiarkowanie).', '8 km progresji, ostatnie 2 km w tempie 10 km.', '', 'Każdy kilometr szybszy od poprzedniego. Ostatni: [szedłem|szłam] na rekord. Nie [doszedłem|doszłam].', 'TIME', 'min:s / ostatni km'),
('d04-sila-wytrzymalosciowca', 'STRENGTH', 'SIŁA DLA WYTRZYMAŁOŚCIOWCA', '30 minut siły, która chroni kolana, ścięgna i ekonomię ruchu.', 'Trening siłowy to najlepsza polisa ubezpieczeniowa biegacza i kolarza. Krótko, konkretnie, z naciskiem na jedną nogę, tylną taśmę i łydki.', '["Przysiad bułgarski: 3 × 8 na nogę (z hantlami lub plecakiem).","Martwy ciąg rumuński: 3 × 10.","Wspięcia na palce na schodku, wolno w dół: 3 × 15 na nogę.","Deska bokiem z unoszeniem biodra: 3 × 10 na stronę.","Odpoczynek 60–90 s między seriami."]'::jsonb, 'Ciężar dobierz tak, żeby po każdej serii zostały 2 powtórzenia w zapasie. Technika ponad kilogramy.', 'MEDIUM', 35, '["Hantle, kettlebell lub obciążony plecak","Schodek"]'::jsonb, 'BASIC', 'dumbbell', 'Bez obciążenia, 2 serie każdego ćwiczenia.', '4 serie z cięższym obciążeniem i dodatkowo 3 × 6 nordic curl negatywnie.', 'Przy bólu kolana w przysiadzie bułgarskim skróć zakres ruchu lub zamień na wykrok w tył.', 'Dzień siłowy dla [wytrzymałościowca|wytrzymałościowczyni]. Łydki zgłaszają sprzeciw.', 'WEIGHT', 'kg'),
('d05-90-minut-ruchu', 'MULTISPORT', '90 MINUT RUCHU', 'Sobota. Półtorej godziny w strefie 2, w dowolnej dyscyplinie.', 'Pierwszy weekendowy blok bazy tlenowej. Biegasz, jeździsz, pływasz, idziesz w góry? Wszystko się liczy, byle 90 minut ruchu w spokojnej intensywności. Możesz też łączyć dyscypliny.', '["Wybierz dyscyplinę albo połączenie (np. 60 min roweru + 30 min biegu).","Trzymaj się strefy 2 przez cały czas, łącznie z podjazdami.","Weź wodę i coś do jedzenia, jeśli wychodzisz na dłużej niż godzinę.","Zapisz łączny czas i dystans."]'::jsonb, 'Pierwsze 20 minut zrób wolniej, niż masz ochotę. Ostatnie 20 minut pokaże, czy siły były dobrze rozłożone.', 'MEDIUM', 90, '[]'::jsonb, 'NONE', 'activity', '60 minut ruchu, w tym marsz.', '2 godziny, a ostatnie 15 minut w Z3.', 'Zimą ubierz się warstwowo i weź dodatkową warstwę na postoje.', '90 minut w strefie 2. Nudne? Może. Skuteczne? Bardzo.', 'TIME', 'h:min'),
('d06-mikolajkowe-szostki', 'RUNNING', 'MIKOŁAJKOWE SZÓSTKI', '6 grudnia: 6 km z sześcioma przyspieszeniami.', 'Mikołajki w wersji biegowej. Spokojne 6 km, a w środku sześć odcinków po minucie w tempie 5 km. Prezent dla serca i dla ekonomii biegu.', '["Pierwsze 2 km spokojnie, jako rozgrzewka.","Następnie 6 × 1 minuta szybko (tempo 5 km) / 1 minuta truchtu.","Resztę do 6 km dobiegnij spokojnie.","Bonus: czapka Mikołaja na głowie podczas przyspieszeń."]'::jsonb, 'Szybko nie znaczy sprint. Ostatnia minuta ma być tak samo szybka jak pierwsza.', 'MEDIUM', 40, '[]'::jsonb, 'NONE', 'gift', '6 × 30 s szybciej w trakcie 5 km biegu z marszem.', '6 km + 6 × 2 minuty w tempie 5 km.', '', 'Mikołajkowe szóstki. Mikołaj przyniósł zakwasy.', 'DISTANCE', 'km'),
('d07-plywanie-technika', 'SWIMMING', '1000 M Z TECHNIKĄ', 'Basen, kilometr i ćwiczenia, które poprawiają każdy styl.', 'Dzień w wodzie: regeneracja dla nóg po weekendzie i praca nad techniką. Kilometr podzielony na rozgrzewkę, ćwiczenia techniczne i spokojne pływanie.', '["Rozgrzewka: 200 m dowolnym stylem, spokojnie.","Technika: 4 × 50 m (catch-up, pływanie na boku, „zamek błyskawiczny”, normalnie), przerwa 20 s.","Główna część: 4 × 100 m spokojnie, przerwa 20 s.","Schłodzenie: 200 m dowolnie. Zapisz łączny czas."]'::jsonb, 'W kraulu wydychaj powietrze pod wodą przez cały czas. Wstrzymany oddech to najczęstszy powód zmęczenia.', 'MEDIUM', 45, '["Basen","Okularki"]'::jsonb, 'FACILITY', 'waves', '500 m z przerwami przy każdej ścianie, dowolnym stylem.', '1600 m: dodaj 4 × 100 m w tempie progowym.', 'Tylko na strzeżonym basenie.', 'Kilometr w basenie. Fale [robiłem|robiłam] tylko ja.', 'TIME', 'min:s'),
('d08-podbiegi', 'HIKING', 'PODBIEGI 8 × 45 S', 'Jedna górka, osiem razy. Siła biegowa bez siłowni.', 'Krótkie podbiegi to siła i moc dla nóg przy niskim obciążeniu stawów. Szukasz wzniesienia o umiarkowanym nachyleniu i wbiegasz na nie mocno, ale z dobrą techniką.', '["Rozgrzewka: 15 minut truchtu i 3 przebieżki.","8 × 45 s podbiegu w mocnym tempie (RPE 8/10), krótki krok, mocna praca rąk.","Powrót w dół truchtem lub marszem: to Twoja przerwa.","Schłodzenie: 10 minut truchtu."]'::jsonb, 'Patrz kilka metrów przed siebie, nie pod nogi. Pochylenie z kostek, nie z bioder.', 'MEDIUM', 45, '[]'::jsonb, 'NONE', 'mountain', '5 podbiegów po 30 s lub szybkie podejścia pod górkę.', '10 × 60 s albo podbiegi na dłuższym, bardziej stromym wzniesieniu.', 'Przy oblodzeniu zamień podbiegi na schody w budynku albo trenażer.', 'Ta górka i ja mamy teraz skomplikowaną relację. 8:0 dla mnie.', 'REPS', 'podbiegów'),
('d09-sweet-spot', 'CYCLING', 'SWEET SPOT 3 × 10', 'Rower lub trenażer. Najlepszy stosunek efektu do zmęczenia.', 'Sweet spot to intensywność tuż poniżej progu (ok. 88–93% FTP): wystarczająco mocna, żeby budować wytrzymałość, i wystarczająco łagodna, żeby nie zabić tygodnia. Klasyk zimowego trenażera.', '["Rozgrzewka: 15 minut spokojnie, z 3 × 1 min wysokiej kadencji.","3 × 10 minut w sweet spot (88–93% FTP lub RPE 7/10), przerwa 5 minut spokojnie.","Schłodzenie: 10 minut bardzo lekko.","Zapisz średnią moc z bloków (bez miernika mocy wpisz wynik po swojemu, np. średnie tętno)."]'::jsonb, 'Bez miernika mocy: oddech mocny, ale możesz powiedzieć kilka słów. Kadencja 85–95.', 'MEDIUM', 60, '["Rower, trenażer lub rower stacjonarny"]'::jsonb, 'BASIC', 'bike', '3 × 6 minut z przerwą 4 minuty.', '3 × 15 minut albo 2 × 20 minut.', 'Na trenażerze: wentylator i woda. Przegrzanie jest realne nawet zimą.', '3 × 10 minut sweet spot. Sweet to kłamstwo, spot się zgadza.', 'COUNT', 'W'),
('d10-kostki-lydki', 'MOBILITY', 'KOSTKI I ŁYDKI', 'Zmierz zakres kostki, popracuj 15 minut, zmierz jeszcze raz.', 'Sztywne kostki i przeciążone łydki to codzienność biegaczy i kolarzy. Dziś robisz test kolano do ściany, zestaw mobilizacji i drugi pomiar. Poprawa w jednej sesji potrafi zaskoczyć.', '["Test: stań przodem do ściany i szukaj największej odległości palców od ściany, przy której kolano dotyka ściany, a pięta zostaje na podłodze.","Rolowanie łydek: 2 minuty na nogę.","Kołysanie kolanem nad palcami przy ścianie: 2 × 15 na nogę.","Wspięcia na palce z wolnym opuszczaniem: 2 × 12 na nogę.","Powtórz test i zapisz wynik w centymetrach."]'::jsonb, 'Ok. 10 cm to dobry wynik. Mniej niż 5 cm to sygnał, żeby wracać do tego zestawu częściej.', 'EASY', 20, '["Linijka lub miarka","Roller lub butelka"]'::jsonb, 'NONE', 'ruler', 'Sam test i rolowanie.', 'Dodaj mobilizację z gumą oporową i wspięcia na jednej nodze z ciężarem.', '', 'Kostki: +2 cm w 15 minut. Nauka!', 'DISTANCE', 'cm'),
('d11-fartlek', 'RUNNING', 'FARTLEK 30 MINUT', 'Zabawa szybkością bez sztywnego planu. Latarnie, zakręty, piosenki.', 'Fartlek to szwedzka „zabawa szybkością”: w trakcie biegu dowolnie przyspieszasz i zwalniasz, korzystając z terenu i otoczenia. Piątek, więc z luzem, ale z jakością.', '["Rozgrzewka: 10 minut truchtu.","30 minut fartleku: przyspieszenia od 20 s do 2 minut, w dowolnej kolejności, przeplatane truchtem.","Pomysły: szybko do następnej latarni, przez refren piosenki, do końca ulicy.","Schłodzenie: 5 minut. Zapisz łączny dystans."]'::jsonb, 'Łącznie szybkie odcinki powinny zająć ok. 1/3 czasu fartleku. Reszta to trucht.', 'MEDIUM', 45, '[]'::jsonb, 'NONE', 'zap', '20 minut fartleku z marszem zamiast truchtu.', '40 minut fartleku z kilkoma odcinkami pod górę.', 'Po zmroku: odblaski i trasa z dobrym oświetleniem.', 'Fartlek: [pokonałem|pokonałam] 47 latarni. Latarnie nie stawiały oporu.', 'DISTANCE', 'km'),
('d12-500-m-w-gore', 'HIKING', '300 M W GÓRĘ', 'Zbierz 300 metrów przewyższenia. Dowolnie: bieg, rower, marsz, schody.', 'Klasyczne wyzwanie wspinaczkowe w stylu Stravy: zbierz łącznie 300 metrów przewyższenia w jednej aktywności. W górach to spacer, na nizinach kreatywne zbieranie pagórków, wiaduktów i klatek schodowych.', '["Zaplanuj trasę z jak największą liczbą wzniesień (Strava lub Komoot pokażą przewyższenie).","Biegnij, jedź lub idź, zbierając metry w górę. Powtórki tej samej górki są w pełni legalne.","Na nizinach: każde piętro w bloku to ok. 3 m przewyższenia.","Zrób zrzut z przewyższeniem z zegarka lub aplikacji."]'::jsonb, 'Barometryczny zegarek liczy przewyższenie dokładniej niż sam GPS. Na schodach licz piętra.', 'MEDIUM', 75, '[]'::jsonb, 'NONE', 'mountain', '150 m przewyższenia, marszem.', '500–1000 m przewyższenia (w górach albo na rowerze w pagórkowatym terenie).', 'W górach sprawdź prognozę i godzinę zachodu słońca. Przy oblodzeniu: raczki lub zostań w niższym terenie.', '300 metrów w górę. Everest to 8849, więc jeszcze tylko 29 takich sobót.', 'DISTANCE', 'm przewyższenia'),
('d13-dlugie-wybieganie', 'RUNNING', 'DŁUGIE WYBIEGANIE', 'Niedziela, 75–90 minut spokojnie. Najważniejszy trening tygodnia.', 'Długie wybieganie buduje wytrzymałość, ekonomię i głowę. Tempo spokojne, bez zegarka na każdym kilometrze. Liczy się czas na nogach, a nie średnie tempo.', '["Zaplanuj trasę na 75–90 minut, najlepiej pętlę z możliwością skrócenia.","Biegnij w strefie 2, a podbiegi pokonuj spokojniej, nawet marszem.","Od 45. minuty pij lub zjedz coś co 30 minut.","Po biegu: jedzenie z białkiem i węglowodanami w ciągu godziny. Zapisz dystans."]'::jsonb, 'Jeśli ostatnie 15 minut jest dużo trudniejsze niż pierwsze, następnym razem zacznij wolniej.', 'HARD', 90, '[]'::jsonb, 'NONE', 'footprints', '60 minut biegu lub biegu z marszem.', '2 godziny, ostatnie 20 minut w tempie maratońskim.', 'Weź telefon i powiedz komuś, którędy biegniesz. Zimą zabierz cienką kurtkę na wypadek wiatru.', 'Długie wybieganie. Najlepsze myśli przychodzą w 70. minucie. Najgorsze w 85.', 'DISTANCE', 'km'),
('d14-aktywna-regeneracja', 'HIKING', 'AKTYWNA REGENERACJA', '45 minut marszu bez zegarka i 10 minut rolowania.', 'Po weekendzie z dużą objętością dzień, w którym ruszasz się, ale nie trenujesz. Szybki spacer, najlepiej w terenie, bez słuchawek i bez patrzenia na tempo, a na koniec rolowanie.', '["45 minut marszu w swobodnym tempie (park, las, wały).","Telefon w kieszeni. Bez podcastów, muzyki i scrollowania.","Po powrocie: rolowanie łydek, ud i pośladków, po 2 minuty na partię.","Zanotuj, jak czują się nogi w skali 1–10."]'::jsonb, 'Regeneracja to też trening. Najwięcej formy budujesz właśnie w dni lekkie.', 'EASY', 55, '[]'::jsonb, 'NONE', 'trees', '30 minut spaceru.', '60 minut marszu z kijami w pagórkowatym terenie, nadal w Z1.', '', 'Dzień lekki. Nie [trenowałem|trenowałam]. [Regenerowałem|Regenerowałam] się profesjonalnie.', 'DISTANCE', 'km'),
('d15-test-5-km', 'RUNNING', 'TEST 5 KM', 'Półmetek kalendarza. Uczciwe 5 km na czas.', 'Środek grudnia to dobry moment na sprawdzian. 5 km na czas: równe tempo, mocny finisz, wynik, do którego porównasz się wiosną. Wszyscy uczestnicy robią ten sam test tego samego dnia.', '["Rozgrzewka: 15 minut truchtu, 4 przebieżki, 2 minuty marszu.","Płaska trasa lub bieżnia lekkoatletyczna. 5 km na czas.","Pierwszy kilometr kontrolowany, kilometry 2–4 równo, ostatni wszystko, co zostało.","Schłodzenie: 10 minut truchtu. Zapisz czas."]'::jsonb, 'Plan na tempo ustal przed startem i trzymaj się go do 3. kilometra. Dopiero potem możesz improwizować.', 'HARD', 50, '[]'::jsonb, 'NONE', 'timer', '3 km na czas albo 5 km w tempie progowym („mocno, ale kontrolowanie”, bez finiszu na maksa).', 'Po 5 km przerwa 5 minut i dodatkowe 2 × 1 km w tempie testu.', 'Nie rób testu przy przeziębieniu ani po nieprzespanej nocy. Przy oblodzeniu lub śniegu biegnij na bieżni albo przełóż test na inny dzień. Przy bólu w klatce piersiowej natychmiast przerwij.', 'Test 5 km na półmetku kalendarza. Wynik poniżej, komentarze o tempie tylko pozytywne.', 'TIME', 'min:s'),
('d16-stabilizacja-plyo', 'STRENGTH', 'STABILIZACJA I SKOCZNOŚĆ', 'Sprężyste ścięgna i stabilne biodra w 30 minut.', 'Lekka plyometria i stabilizacja to sekret ekonomii biegu i mocy na rowerze. Mało powtórzeń, pełna jakość, dużo kontroli.', '["Skakanka lub podskoki A: 3 × 45 s.","Wyskoki na skrzynię lub schodek (miękkie lądowanie): 3 × 6.","Przeskoki boczne na jednej nodze: 3 × 10 na stronę.","Martwy robak: 3 × 10 na stronę. Przysiad na jednej nodze do krzesła: 3 × 8 na stronę.","Odpoczynek 60 s między seriami."]'::jsonb, 'Plyometria liczy się jakością. Gdy lądowania robią się głośne, zakończ serię.', 'MEDIUM', 30, '["Skakanka (opcjonalnie)","Stabilny schodek lub skrzynia"]'::jsonb, 'BASIC', 'zap', 'Bez wyskoków: wspięcia na palce, mosty biodrowe, martwy robak i przysiad do krzesła.', 'Dodaj wieloskoki 3 × 20 m i przeskoki przez płotki z kartonu.', 'Skacz na miękkim podłożu. Przy bólu ścięgna Achillesa pomiń skoki i zrób wersję łatwiejszą.', 'Plyometria: [lądowałem|lądowałam] miękko jak kot. Prawie zawsze.', 'NOTE', ''),
('d17-kadencja', 'CYCLING', 'KADENCJA 100+', '45 minut kręcenia z blokami bardzo wysokiej kadencji.', 'Trening techniki pedałowania: przy niskim oporze kręcisz bardzo szybko, ucząc się płynnego, okrągłego ruchu bez podskakiwania na siodełku. Lekko dla mięśni, ciężko dla koordynacji.', '["Rozgrzewka: 10 minut, kadencja 85–90.","6 × 2 minuty z kadencją 100–110 (niski opór), przerwa 2 minuty z kadencją 85.","Na koniec 3 × 30 s z maksymalną kadencją bez podskakiwania.","Schłodzenie: 5 minut. Zapisz najwyższą utrzymaną kadencję."]'::jsonb, 'Jeśli zaczynasz podskakiwać na siodełku, obniż kadencję o 5 i rozluźnij barki.', 'EASY', 45, '["Rower lub trenażer z czujnikiem kadencji (opcjonalnie)"]'::jsonb, 'BASIC', 'bike', '30 minut, 4 bloki po 1 minucie.', '60 minut i bloki po 3 minuty z kadencją 105–115.', '', 'Kadencja 110. Nogi wirowały jak mikser. Siodełko przetrwało.', 'COUNT', 'rpm'),
('d18-piramida-plywacka', 'SWIMMING', 'PIRAMIDA W WODZIE', '50-100-150-200-150-100-50. Basen w kształcie choinki.', 'Piramida pływacka: odcinki rosną do 200 m i z powrotem. Łącznie 800 m głównej części, z tempem równym na każdym odcinku. Po drodze wiesz dokładnie, ile zostało.', '["Rozgrzewka: 300 m spokojnie, w tym 100 m innym stylem.","Piramida: 50, 100, 150, 200, 150, 100, 50 m, przerwa 20–30 s po każdym.","Tempo: umiarkowanie mocne i równe na wszystkich odcinkach.","Schłodzenie: 200 m. Zapisz czas odcinka 200 m."]'::jsonb, 'Licz baseny na palcach albo ustaw licznik w zegarku. W połowie 200 m łatwo się pogubić.', 'MEDIUM', 45, '["Basen","Okularki"]'::jsonb, 'FACILITY', 'waves', 'Piramida do 100 m: 50-100-50, z dłuższymi przerwami.', 'Piramida do 400 m: 100-200-300-400-300-200-100.', 'Tylko na strzeżonym basenie.', 'Piramida w basenie. Faraon byłby zmęczony. Ja jestem.', 'TIME', 'min:s / 200 m'),
('d19-dluga-wyprawa', 'CYCLING', 'WEEKENDOWA WYPRAWA', '50 km na rowerze albo 2,5 godziny w terenie. Ostatni duży weekend.', 'Najdłuższy trening kalendarza. Na rowerze 50 km (szosa, gravel, MTB), a pieszo lub biegowo 2,5 godziny w terenie. Z przystankiem na ciepły napój, bo to też część wyprawy.', '["Zaplanuj trasę z punktem na postój (kawiarnia, schronisko, stacja).","Jedź lub idź w Z2, a podjazdy spokojnie.","Jedz co 30–45 minut i pij regularnie, nawet gdy jest zimno.","Zapisz dystans i zrób zdjęcie w najładniejszym punkcie trasy."]'::jsonb, 'Zimą najwięcej ciepła tracisz przez dłonie, stopy i głowę. Ochraniacze na buty robią różnicę.', 'HARD', 150, '["Rower (lub buty trailowe)","Jedzenie i picie"]'::jsonb, 'BASIC', 'bike', '30 km na rowerze albo 90 minut w terenie.', '80 km na rowerze albo 3,5 godziny w górach.', 'Kask, oświetlenie przód i tył, odblaski. Sprawdź prognozę i godzinę zachodu słońca, w grudniu ok. 15:30.', '50 km w grudniu. Tak, z własnej woli. Tak, było warto.', 'DISTANCE', 'km'),
('d20-brick', 'MULTISPORT', 'BRICK: ROWER + BIEG', 'Triatlonowa cegła: 45 minut roweru i od razu 15 minut biegu.', 'Trening „brick” znany z triatlonu uczy ciało przechodzić z jednej dyscypliny w drugą. Po rowerze nogi przez kilka minut zapominają, jak się biega, i to jest dokładnie ten moment, który trenujesz.', '["Rower lub trenażer: 45 minut, w tym ostatnie 10 minut w Z3.","Przejście poniżej 3 minut: buty, łyk wody, start.","Bieg: 15 minut, pierwsze 5 spokojnie, potem równe tempo.","Zapisz wrażenia z pierwszego kilometra jednym słowem."]'::jsonb, 'Pierwsze minuty biegu po rowerze są dziwne dla wszystkich. Krótki, szybki krok pomaga je przetrwać.', 'MEDIUM', 65, '["Rower lub trenażer","Buty biegowe"]'::jsonb, 'BASIC', 'repeat', '30 minut roweru + 10 minut biegu z marszem.', '75 minut roweru + 30 minut biegu, ostatnie 10 w tempie 10 km.', '', 'Brick: nogi z waty na pierwszym kilometrze. Triatlon, czekam na zaproszenie.', 'NOTE', ''),
('d21-najkrotszy-dzien', 'RUNNING', 'BIEG W NAJKRÓTSZY DZIEŃ', 'Przesilenie zimowe. 45 minut o świcie albo o zmierzchu.', '21 grudnia to najkrótszy dzień roku: w Polsce niecałe 8 godzin światła. Celebrujesz go biegiem o wschodzie albo zachodzie słońca. Od jutra dni są już tylko dłuższe.', '["Sprawdź godzinę wschodu (ok. 7:45) albo zachodu słońca (ok. 15:25) w swoim mieście.","Biegnij 45 minut spokojnie, tak żeby wschód lub zachód wypadł w trakcie.","Zatrzymaj się na minutę i popatrz. Telefon dopiero potem.","Zrób zdjęcie nieba i zapisz dystans."]'::jsonb, 'Od jutra dzień zaczyna się wydłużać: najpierw o kilka sekund dziennie, w styczniu już o kilka minut tygodniowo.', 'EASY', 45, '["Czołówka","Odblaski"]'::jsonb, 'BASIC', 'sun', '30 minut biegu z marszem.', 'Dwa biegi: 30 minut o wschodzie i 30 minut o zachodzie.', 'O zmierzchu i świcie jest ciemno: czołówka, odblaski i jasne ubranie.', 'Najkrótszy dzień roku. Od jutra już tylko jaśniej. Ja też.', 'DISTANCE', 'km'),
('d22-interwaly', 'RUNNING', 'INTERWAŁY 5 × 3 MINUTY', 'Ostatnia mocna jednostka przed świętami. VO2max w praktyce.', 'Pięć odcinków po trzy minuty w tempie ok. 3–5 km, z równą przerwą. Najmocniejszy trening tygodnia, który zostawia na święta przyjemne zmęczenie i satysfakcję.', '["Rozgrzewka: 15 minut truchtu, 4 przebieżki.","5 × 3 minuty mocno (RPE 8–9/10), przerwa 2 minuty truchtu.","Wszystkie odcinki w podobnym tempie: ostatni nie może być dużo wolniejszy niż pierwszy.","Schłodzenie: 10 minut. Zapisz średnie tempo odcinków."]'::jsonb, 'Jeśli 4. odcinek jest wyraźnie wolniejszy, zakończ na nim. To nadal pełnowartościowy trening.', 'HARD', 50, '[]'::jsonb, 'NONE', 'timer', '4 × 2 minuty z przerwą 2 minuty.', '6 × 3 minuty albo 5 × 4 minuty.', 'Wysoka intensywność: tylko po rozgrzewce i gdy czujesz się zdrowo.', '5 × 3 minuty. Najdłuższe 15 minut grudnia. [Przeżyłem|Przeżyłam].', 'TIME', 'min:s / km (średnio)'),
('d23-joga-wytrzymalosciowa', 'MOBILITY', 'JOGA DLA WYTRZYMAŁOŚCIOWCÓW', '30 minut na macie przed świętami. Plecy, biodra, oddech.', 'Dzień przed Wigilią to dobry moment na wyciszenie. Sesja jogi skrojona pod biegaczy, kolarzy i pływaków: odcinek piersiowy, biodra, tył uda i dłuższy wydech.', '["Pies z głową w dół i kobra na zmianę: 10 razy.","Wykrok niski z rotacją: 5 oddechów na stronę.","Półszpagat (rozciąganie tyłu uda): 60 s na stronę.","Nitkowanie igły: 5 oddechów na stronę. Pozycja dziecka: 2 minuty.","Na koniec 5 minut leżenia z nogami na ścianie i oddychania 4-6 (wdech 4 s, wydech 6 s)."]'::jsonb, 'Kolarze: więcej czasu na odcinek piersiowy i zginacze bioder. Pływacy: na barki i klatkę.', 'EASY', 30, '["Mata lub koc"]'::jsonb, 'NONE', 'feather', '15 minut: pies, kobra, pozycja dziecka i nogi na ścianie.', '45–60 minut zajęć vinyasy online lub w studiu.', '', 'Joga przed świętami. [Przyszedłem|Przyszłam] jako deska, [wyszedłem|wyszłam] jako trochę mniejsza deska.', 'NOTE', ''),
('d24-wigilijny-rozruch', 'MULTISPORT', 'WIGILIJNY ROZRUCH 24', '24 minuty ruchu, 24 przysiady, 24 sekundy deski. Meta kalendarza.', 'Finał THE ADVENT SPLITS. Krótki, symboliczny rozruch przed wieczerzą: 24 minuty spokojnej aktywności w dowolnej dyscyplinie, a potem mini-zestaw z liczbą 24 w roli głównej. Na koniec zdjęcie z medalem z Twojego kalendarza.', '["24 minuty spokojnego ruchu: bieg, rower, pływanie albo szybki marsz.","Od razu potem: 24 przysiady, 24 wykroki (12 na nogę), 24 s deski.","Opcjonalnie z rodziną: każdy robi tyle przysiadów, ile da radę bez zadyszki. Liczy się wspólne zdjęcie, nie wynik.","Zrób zdjęcie i pochwal się podsumowaniem grudnia."]'::jsonb, 'Zrób to rano, zanim zacznie się gotowanie. Wieczorem nikt Cię już nie wypuści z domu.', 'EASY', 35, '[]'::jsonb, 'NONE', 'star', '24 minuty spaceru i 12 przysiadów.', '24 minuty w tempie progowym + zestaw × 2.', '', 'Dzień 24. Meta. Kalendarz [zamknąłem|zamknęłam], pierogi czekają.', 'NOTE', '')
